mapper.select:
select id, user_id, scenic_area_id, route_name, geojson, spot_ids_json, spot_names_json, distance_meters, spot_count, road_segment_count, create_time, update_time from agent_route_geo where user_id = #{userId}
and scenic_area_id = #{scenicAreaId}
order by create_time desc, id desc limit 1
